-- Private evidence attached to a server-owned material request. Object keys are
-- generated by the server and never reused; only STORED rows may be downloaded.
CREATE TABLE IF NOT EXISTS portal_evidence (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenants(id),
  project_id uuid NOT NULL REFERENCES portal_annual_projects(id),
  material_request_id uuid NOT NULL REFERENCES portal_project_records(id),
  version integer NOT NULL CHECK (version > 0),
  object_key text NOT NULL UNIQUE,
  filename text NOT NULL CHECK (char_length(filename) BETWEEN 1 AND 180),
  media_type text NOT NULL CHECK (media_type IN ('text/plain; charset=utf-8', 'text/csv; charset=utf-8')),
  byte_length integer NOT NULL CHECK (byte_length BETWEEN 1 AND 2097152),
  sha256 char(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'STORED', 'FAILED')),
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  stored_at timestamptz,
  UNIQUE (material_request_id, version),
  FOREIGN KEY (tenant_id, created_by) REFERENCES tenant_memberships(tenant_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_portal_evidence_scope ON portal_evidence(tenant_id, project_id, material_request_id, created_at DESC);
